"""Reconcile the scenario matrix against the scenario ids the tests carry."""

from __future__ import annotations

import ast
import re
from collections import defaultdict
from pathlib import Path

DOC = Path("docs/dev/package-sync-scenario-coverage.md")
TESTS = Path("tests")

ID = re.compile(r"\b([A-KN]\d{1,3}[a-z]?)\b")
# A docstring tags its scenarios in the opening clause: "A2, A3 — ..." / "A2: ..."
LEAD = re.compile(r"^\s*((?:[A-KN]\d{1,3}[a-z]?)(?:\s*[,/]\s*[A-KN]\d{1,3}[a-z]?)*)\s*[—:-]")


def tagged_ids() -> dict[str, list[str]]:
    """scenario id -> [module:Class::test] taken from docstrings."""
    found: dict[str, list[str]] = defaultdict(list)
    for path in sorted(TESTS.rglob("test_*.py")):
        try:
            tree = ast.parse(path.read_text())
        except SyntaxError:
            continue
        module = path.stem
        for node in ast.walk(tree):
            if not isinstance(node, ast.ClassDef):
                continue
            for item in node.body:
                if not isinstance(item, ast.FunctionDef | ast.AsyncFunctionDef):
                    continue
                doc = ast.get_docstring(item) or ""
                m = LEAD.match(doc)
                if not m:
                    continue
                for sid in ID.findall(m.group(1)):
                    found[sid].append(f"{module}:{node.name}::{item.name}")
    return found


def matrix_rows() -> dict[str, tuple[str, str]]:
    """scenario id -> (Cov, Test)."""
    rows: dict[str, tuple[str, str]] = {}
    for line in DOC.read_text().splitlines():
        if not re.match(r"^\| [A-KN]\d", line):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split(" | ")]
        if len(cells) == 5:
            rows[cells[0]] = (cells[3], cells[4])
    return rows


rows = matrix_rows()
tags = tagged_ids()

untagged_covered = sorted(
    sid for sid, (cov, _) in rows.items() if cov in {"U", "U V"} and sid not in tags
)
tagged_uncovered = sorted(sid for sid in tags if rows.get(sid, ("", ""))[0] in {"—", "P"})
orphan_tags = sorted(sid for sid in tags if sid not in rows)

print(f"matrix rows: {len(rows)}   ids carried by tests: {len(tags)}")
print(f"\nrows marked covered but no test carries the id ({len(untagged_covered)}):")
print("  " + " ".join(untagged_covered))
print(f"\nrows still marked '—' or 'P' though a test now carries the id ({len(tagged_uncovered)}):")
for sid in tagged_uncovered:
    print(f"  {sid} [{rows[sid][0]}] -> {', '.join(tags[sid])}")
print(f"\nids carried by a test but absent from the matrix ({len(orphan_tags)}):")
for sid in orphan_tags:
    print(f"  {sid} -> {', '.join(tags[sid])}")

